#include <stdio.h>

unsigned long long fact(unsigned n)
{
    if (n == 0) { return 1; }
    return n * fact(n - 1);
}

int main(void)
{
    printf("%llu\n", fact(3));
    return 0;
}

#include <stdio.h>

int sum_to(int n)
{
    if (n == 0) { return 0; }
    return n + sum_to(n - 1);
}

int main(void)
{
    printf("%d\n", sum_to(4));
    return 0;
}

#include <stdio.h>

int main(void)
{
    unsigned long long result = 1;
    for (unsigned i = 1; i <= 5; i++) { result *= i; }
    printf("%llu\n", result);
    return 0;
}

